export default function NotFoundPage() {
  const [query, setQuery] = useState("");
  const [showCookieBanner, setShowCookieBanner] = useState(false);
  const [showCookieModal, setShowCookieModal] = useState(false);
  const [analyticsChecked, setAnalyticsChecked] = useState(true);
  const [personalizationChecked, setPersonalizationChecked] = useState(true);
  const [advertisingChecked, setAdvertisingChecked] = useState(true);
  const modalRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const consent = localStorage.getItem("ideaforum-cookie-consent");
    if (!consent) {
      setShowCookieBanner(true);
    }
  }, []);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (modalRef.current && !modalRef.current.contains(event.target as Node)) {
        setShowCookieModal(false);
      }
    }
    if (showCookieModal) {
      document.addEventListener("mousedown", handleClickOutside);
    }
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [showCookieModal]);

  function handleSearch(e: React.FormEvent) {
    e.preventDefault();
    if (query.trim()) {
      window.location.href = `https://www.google.com/search?q=site:ideaforum.org+${encodeURIComponent(query.trim())}`;
    }
  }

  function acceptAllCookies() {
    localStorage.setItem("ideaforum-cookie-consent", "all");
    setShowCookieBanner(false);
  }

  function savePreferences() {
    localStorage.setItem(
      "ideaforum-cookie-consent",
      JSON.stringify({
        essential: true,
        analytics: analyticsChecked,
        personalization: personalizationChecked,
        advertising: advertisingChecked,
      })
    );
    setShowCookieBanner(false);
    setShowCookieModal(false);
  }

  return (
    <div className={styles.page}>
      <main className={styles.main}>
        <IdeaForumLogo />

        <h1 className={styles.heading}>Sorry, we can&apos;t find that.</h1>
        <p className={styles.subheading}>
          Perhaps we can help you find the content you&apos;re looking for:
        </p>

        <form className={styles.searchForm} onSubmit={handleSearch}>
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Search IdeaForum..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            aria-label="Search IdeaForum"
          />
          <button
            type="submit"
            className={styles.searchButton}
            aria-label="Search"
          >
            <SearchIcon />
          </button>
        </form>

        <div className={styles.errorCode}>HTTP Error 404</div>

        <hr className={styles.divider} />

        <div className={styles.nextSteps}>
          <h2 className={styles.nextStepsHeading}>What&apos;s next?</h2>
          <nav className={styles.links} aria-label="Recovery navigation">
            <a href="/" className={styles.link}>
              Go to the homepage
            </a>
            <a href="/help" className={styles.link}>
              Visit our Help Desk
            </a>
          </nav>
        </div>
      </main>

      {showCookieBanner && (
        <div className={styles.cookieBanner} role="region" aria-label="Cookie consent">
          <div className={styles.cookieContent}>
            <p className={styles.cookieText}>
              This website utilizes technologies such as cookies to enable essential site
              functionality, as well as for analytics, personalization, and targeted
              advertising. To learn more, view the following link:{" "}
              <a
                href="/privacy"
                target="_blank"
                rel="noopener noreferrer"
                className={styles.privacyLink}
              >
                Privacy Policy
              </a>
            </p>
            <div className={styles.cookieActions}>
              <button
                className={styles.manageButton}
                onClick={() => setShowCookieModal(true)}
              >
                Manage Preferences
              </button>
              <button className={styles.acceptButton} onClick={acceptAllCookies}>
                Accept All
              </button>
            </div>
          </div>
        </div>
      )}

      {showCookieModal && (
        <div className={styles.modalOverlay} role="dialog" aria-modal="true" aria-label="Cookie preferences">
          <div className={styles.modal} ref={modalRef}>
            <div className={styles.modalHeader}>
              <h3 className={styles.modalTitle}>Cookie Preferences</h3>
              <button
                className={styles.modalClose}
                onClick={() => setShowCookieModal(false)}
                aria-label="Close"
              >
                <CloseIcon />
              </button>
            </div>
            <div className={styles.modalBody}>
              <div className={styles.preferenceItem}>
                <div className={styles.preferenceInfo}>
                  <span className={styles.preferenceName}>Essential</span>
                  <span className={styles.preferenceDesc}>
                    Required for the site to function. Cannot be disabled.
                  </span>
                </div>
                <input type="checkbox" checked disabled className={styles.checkbox} />
              </div>
              <div className={styles.preferenceItem}>
                <div className={styles.preferenceInfo}>
                  <span className={styles.preferenceName}>Analytics</span>
                  <span className={styles.preferenceDesc}>
                    Helps us understand how visitors interact with the site.
                  </span>
                </div>
                <input
                  type="checkbox"
                  checked={analyticsChecked}
                  onChange={(e) => setAnalyticsChecked(e.target.checked)}
                  className={styles.checkbox}
                />
              </div>
              <div className={styles.preferenceItem}>
                <div className={styles.preferenceInfo}>
                  <span className={styles.preferenceName}>Personalization</span>
                  <span className={styles.preferenceDesc}>
                    Allows us to tailor content and recommendations to you.
                  </span>
                </div>
                <input
                  type="checkbox"
                  checked={personalizationChecked}
                  onChange={(e) => setPersonalizationChecked(e.target.checked)}
                  className={styles.checkbox}
                />
              </div>
              <div className={styles.preferenceItem}>
                <div className={styles.preferenceInfo}>
                  <span className={styles.preferenceName}>Advertising</span>
                  <span className={styles.preferenceDesc}>
                    Used to deliver relevant advertisements.
                  </span>
                </div>
                <input
                  type="checkbox"
                  checked={advertisingChecked}
                  onChange={(e) => setAdvertisingChecked(e.target.checked)}
                  className={styles.checkbox}
                />
              </div>
            </div>
            <div className={styles.modalFooter}>
              <button className={styles.saveButton} onClick={savePreferences}>
                Save Preferences
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

.page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 24px 120px;
  background: #ffffff;
}

.main {
  width: 100%;
  max-width: 560px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.logo {
  width: 220px;
  height: auto;
  margin-bottom: 48px;
}

.heading {
  font-size: 1.75rem;
  font-weight: 600;
  color: #121212;
  margin-bottom: 12px;
  line-height: 1.3;
}

.subheading {
  font-size: 1rem;
  font-weight: 400;
  color: #444444;
  margin-bottom: 32px;
  line-height: 1.5;
}

.searchForm {
  width: 100%;
  position: relative;
  margin-bottom: 24px;
}

.searchInput {
  width: 100%;
  padding: 14px 48px 14px 16px;
  font-size: 1rem;
  font-family: inherit;
  color: #121212;
  background: #ffffff;
  border: 1.5px solid #e5e5e5;
  border-radius: 8px;
  outline: none;
  transition: border-color 0.2s ease;
}

.searchInput::placeholder {
  color: #999999;
}

.searchInput:focus {
  border-color: #121212;
}

.searchButton {
  position: absolute;
  right: 4px;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #121212;
  color: #ffffff;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.2s ease;
}

.searchButton:hover {
  background: #333333;
}

.searchButton:active {
  background: #000000;
}

.errorCode {
  display: inline-block;
  padding: 8px 20px;
  font-size: 0.8125rem;
  font-weight: 500;
  color: #696969;
  background: #f5f5f5;
  border-radius: 6px;
  margin-bottom: 32px;
  letter-spacing: 0.02em;
}

.divider {
  width: 100%;
  height: 1px;
  background: #e5e5e5;
  border: none;
  margin-bottom: 32px;
}

.nextSteps {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.nextStepsHeading {
  font-size: 1.125rem;
  font-weight: 600;
  color: #121212;
}

.links {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.link {
  font-size: 1rem;
  font-weight: 500;
  color: #777777;
  text-decoration: underline;
  text-underline-offset: 3px;
  transition: color 0.2s ease;
}

.link:hover {
  color: #121212;
}

/* Cookie Banner */
.cookieBanner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: #ffffff;
  border-top: 1px solid #e5e5e5;
  padding: 20px 24px;
  z-index: 100;
}

.cookieContent {
  max-width: 960px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: flex-start;
}

.cookieText {
  font-size: 0.875rem;
  line-height: 1.5;
  color: #444444;
}

.privacyLink {
  color: #121212;
  text-decoration: underline;
  text-underline-offset: 2px;
  font-weight: 500;
}

.privacyLink:hover {
  color: #eb0028;
}

.cookieActions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.manageButton {
  padding: 10px 20px;
  font-size: 0.875rem;
  font-weight: 500;
  font-family: inherit;
  color: #121212;
  background: #ffffff;
  border: 1.5px solid #e5e5e5;
  border-radius: 6px;
  cursor: pointer;
  transition: border-color 0.2s ease, background 0.2s ease;
}

.manageButton:hover {
  border-color: #121212;
  background: #f9f9f9;
}

.acceptButton {
  padding: 10px 20px;
  font-size: 0.875rem;
  font-weight: 500;
  font-family: inherit;
  color: #ffffff;
  background: #121212;
  border: 1.5px solid #121212;
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.2s ease;
}

.acceptButton:hover {
  background: #333333;
}

/* Cookie Modal */
.modalOverlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  z-index: 200;
}

.modal {
  width: 100%;
  max-width: 480px;
  background: #ffffff;
  border-radius: 12px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.15);
  overflow: hidden;
}

.modalHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  border-bottom: 1px solid #e5e5e5;
}

.modalTitle {
  font-size: 1.125rem;
  font-weight: 600;
  color: #121212;
}

.modalClose {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  color: #777777;
  transition: color 0.2s ease, background 0.2s ease;
}

.modalClose:hover {
  color: #121212;
  background: #f5f5f5;
}

.modalBody {
  padding: 16px 24px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.preferenceItem {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 0;
  border-bottom: 1px solid #f0f0f0;
}

.preferenceItem:last-child {
  border-bottom: none;
}

.preferenceInfo {
  display: flex;
  flex-direction: column;
  gap: 4px;
  text-align: left;
}

.preferenceName {
  font-size: 0.9375rem;
  font-weight: 600;
  color: #121212;
}

.preferenceDesc {
  font-size: 0.8125rem;
  color: #696969;
  line-height: 1.4;
}

.checkbox {
  width: 20px;
  height: 20px;
  accent-color: #121212;
  cursor: pointer;
  flex-shrink: 0;
}

.checkbox:disabled {
  cursor: default;
  opacity: 0.6;
}

.modalFooter {
  padding: 16px 24px 20px;
  display: flex;
  justify-content: flex-end;
  border-top: 1px solid #e5e5e5;
}

.saveButton {
  padding: 10px 24px;
  font-size: 0.875rem;
  font-weight: 500;
  font-family: inherit;
  color: #ffffff;
  background: #121212;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.2s ease;
}

.saveButton:hover {
  background: #333333;
}

/* Responsive */
@media (min-width: 640px) {
  .cookieContent {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }

  .cookieText {
    max-width: 70%;
  }
}

@media (min-width: 768px) {
  .logo {
    width: 280px;
    margin-bottom: 56px;
  }

  .heading {
    font-size: 2rem;
  }

  .subheading {
    font-size: 1.0625rem;
  }

  .searchInput {
    padding: 16px 52px 16px 18px;
    font-size: 1.0625rem;
  }

  .searchButton {
    width: 44px;
    height: 44px;
  }
}
